#include <stdio.h>

long fact(int n);

int main(void)
{
    int n, r;
    long ncr;

    printf("Enter n and r: ");
    scanf("%d %d", &n, &r);

    ncr = fact(n) / (fact(r) * fact(n - r));
    printf("%dC%d = %ld\n", n, r, ncr);
    return 0;
}

long fact(int n)
{
    long f = 1;
    int i;
    for (i = 2; i <= n; i++)
        f = f * i;
    return f;
}

#include <stdio.h>

// returns 1 or 0
int isPrime(int n);

int main(void)
{
    int lo, hi, i, count = 0;

    printf("Enter range (low high): ");
    scanf("%d %d", &lo, &hi);

    printf("Primes: ");
    for (i = lo; i <= hi; i++)
    {
        if (isPrime(i))
        {
            printf("%d ", i);
            count++;
        }
    }
    printf("\nTotal = %d\n", count);
    return 0;
}

int isPrime(int n)
{
    int i;
    if (n < 2)
        return 0;
    for (i = 2; i * i <= n; i++)
        if (n % i == 0)
            // return also ends the loop
            return 0;
    return 1;
}

#include <stdio.h>

void swap_value(int x, int y);
void swap_ref(int *x, int *y);

int main(void)
{
    int a = 10, b = 20;

    // copies passed
    swap_value(a, b);
    printf("After call by value     : a = %d, b = %d\n", a, b);

    // addresses passed
    swap_ref(&a, &b);
    printf("After call by reference : a = %d, b = %d\n", a, b);
    return 0;
}

void swap_value(int x, int y)
{
    int t = x;
    x = y;
    y = t;
    printf("Inside swap_value       : x = %d, y = %d\n", x, y);
}

void swap_ref(int *x, int *y)
{
    int t = *x;
    *x = *y;
    *y = t;
}

#include <stdio.h>

void stats(int a[], int n, int *max, int *min, float *avg);

int main(void)
{
    int m[] = {67, 82, 45, 91, 58};
    int hi, lo;
    float av;

    // 3 results come back
    stats(m, 5, &hi, &lo, &av);
    printf("Max = %d, Min = %d, Average = %.2f\n", hi, lo, av);
    return 0;
}

void stats(int a[], int n, int *max, int *min, float *avg)
{
    int i, sum = 0;
    *max = *min = a[0];
    for (i = 0; i < n; i++)
    {
        if (a[i] > *max) *max = a[i];
        if (a[i] < *min) *min = a[i];
        sum += a[i];
    }
    *avg = (float) sum / n;
}

