// bubble sort
void sort(int x[], int n)
{
    int i, j, t;
    for (i = 0; i < n - 1; i++)
        for (j = 0; j < n - 1 - i; j++)
            if (x[j] > x[j + 1])
            {
                t = x[j]; x[j] = x[j + 1]; x[j + 1] = t;
            }
}

