int total(int m[][3], int rows)
{
    int i, j, s = 0;
    for (i = 0; i < rows; i++)
        for (j = 0; j < 3; j++)
            s += m[i][j];
    return s;
}

#include <stdio.h>

long fact(int n);

int main(void)
{
    int n;
    printf("Enter a number: ");
    scanf("%d", &n);
    printf("%d! = %ld\n", n, fact(n));
    return 0;
}

long fact(int n)
{
    // base case: stops recursion
    if (n <= 1)
        return 1;
    else
        // recursive call
        return n * fact(n - 1);
}

#include <stdio.h>

int fib(int n);

int main(void)
{
    int n, i;
    printf("Enter number of terms: ");
    scanf("%d", &n);

    printf("Fibonacci series: ");
    for (i = 0; i < n; i++)
        printf("%d ", fib(i));
    printf("\n");
    return 0;
}

int fib(int n)
{
    // base cases
    if (n == 0) return 0;
    if (n == 1) return 1;
    // two recursive calls
    return fib(n - 1) + fib(n - 2);
}

#include <stdio.h>

int gcd(int a, int b);
long power(int x, int n);

int main(void)
{
    int a, b, x, n;

    printf("Enter two numbers for GCD: ");
    scanf("%d %d", &a, &b);
    printf("GCD(%d, %d) = %d\n", a, b, gcd(a, b));

    printf("Enter base and exponent: ");
    scanf("%d %d", &x, &n);
    printf("%d ^ %d = %ld\n", x, n, power(x, n));
    return 0;
}

// Euclid's method
int gcd(int a, int b)
{
    if (b == 0)
        return a;
    return gcd(b, a % b);
}

long power(int x, int n)
{
    if (n == 0)
        return 1;
    return x * power(x, n - 1);
}

#include <stdio.h>

// global variable
int g = 100;

void fun(void);

int main(void)
{
    // local to main
    int x = 10;
    printf("main : g = %d, x = %d\n", g, x);
    {
        // block variable hides outer x
        int x = 20;
        printf("block: x = %d\n", x);
    }
    printf("main : x = %d (outer x again)\n", x);
    fun();
    printf("main : g = %d (changed by fun)\n", g);
    return 0;
}

void fun(void)
{
    // different x, local to fun
    int x = 30;
    // global is shared
    g = g + 1;
    printf("fun  : g = %d, x = %d\n", g, x);
}

